msg.payload = {
    status: "REJECTED",
    disposition: "REJECTED",
    reason: "Malformed JSON syntax - payload cannot be parsed",
    parse_error: (msg.error && msg.error.message) ? msg.error.message : "Invalid JSON string",
    topic: msg.topic || "unknown",
    raw_payload: msg.payload,
    gateway_received_at: new Date().toISOString()
};
return msg;

const topic = msg.topic || "";
const payload = msg.payload;
const arrivalTime = new Date().toISOString();

// 1. Verify Topic Pattern: motors/{device_id}/prediction
const topicParts = topic.split('/');
if (topicParts.length !== 3 || topicParts[0] !== 'motors' || topicParts[2] !== 'prediction') {
    msg.payload = {
        status: "REJECTED",
        disposition: "REJECTED",
        reason: `Invalid topic structure: '${topic}'. Expected 'motors/{device_id}/prediction'`,
        topic: topic,
        raw_payload: payload,
        gateway_received_at: arrivalTime
    };
    return [null, msg]; // Route to Output 2 (Rejected)
}
const topicDeviceId = topicParts[1];

// 2. Verify Payload is a JSON Object
if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
    msg.payload = {
        status: "REJECTED",
        disposition: "REJECTED",
        reason: "Payload must be a JSON object",
        topic: topic,
        raw_payload: payload,
        gateway_received_at: arrivalTime
    };
    return [null, msg];
}

// 3. Verify Required Core Fields (Phase 1 Project Requirement)
const missing = [];
if (typeof payload.device_id !== 'string' || payload.device_id.trim() === '') missing.push('device_id');
if (typeof payload.fault_type !== 'string' || payload.fault_type.trim() === '') missing.push('fault_type');
if (payload.health_index === undefined || payload.health_index === null) missing.push('health_index');
if (payload.rul_hours === undefined || payload.rul_hours === null) missing.push('rul_hours');

if (missing.length > 0) {
    msg.payload = {
        status: "REJECTED",
        disposition: "REJECTED",
        reason: `Missing or empty required field(s): ${missing.join(', ')}`,
        topic: topic,
        raw_payload: payload,
        gateway_received_at: arrivalTime
    };
    return [null, msg];
}

// 4. Verify Field Types
if (typeof payload.health_index !== 'number' || isNaN(payload.health_index)) {
    msg.payload = {
        status: "REJECTED",
        disposition: "REJECTED",
        reason: `Invalid data type for 'health_index': expected number, got ${typeof payload.health_index}`,
        topic: topic,
        raw_payload: payload,
        gateway_received_at: arrivalTime
    };
    return [null, msg];
}

if (typeof payload.rul_hours !== 'number' || isNaN(payload.rul_hours)) {
    msg.payload = {
        status: "REJECTED",
        disposition: "REJECTED",
        reason: `Invalid data type for 'rul_hours': expected number, got ${typeof payload.rul_hours}`,
        topic: topic,
        raw_payload: payload,
        gateway_received_at: arrivalTime
    };
    return [null, msg];
}

// 5. Verify Topic Device ID matches Payload Device ID
if (payload.device_id !== topicDeviceId) {
    msg.payload = {
        status: "REJECTED",
        disposition: "REJECTED",
        reason: `Topic / payload device_id mismatch: topic specifies '${topicDeviceId}', but payload contains '${payload.device_id}'`,
        topic: topic,
        raw_payload: payload,
        gateway_received_at: arrivalTime
    };
    return [null, msg];
}

// 6. Timestamp Ingestion Fallback (Phase 1 Recommendation: preserve edge timestamp if present, else fallback)
const timestamp = payload.timestamp || arrivalTime;

// 7. Prepare Normalized Output for Gateway Downstream (Phase 3 InfluxDB Sink)
const normalized = {
    status: "ACCEPTED",
    disposition: "ACCEPTED",
    device_id: payload.device_id,
    fault_type: payload.fault_type,
    health_index: Number(payload.health_index),
    rul_hours: Number(payload.rul_hours),
    timestamp: timestamp,
    gateway_received_at: arrivalTime,
    topic: topic
};

msg.payload = normalized;
return [msg, null]; // Route to Output 1 (Accepted)

// Phase 3 InfluxDB Line Protocol Formatter
// Consumes validated & normalized Phase 2 Output 1
const normalized = msg.payload;

// Retrieve configuration dynamically using Node-RED env.get() API [IMPLEMENTATION DECISION]
const influxUrl = (env.get("INFLUXDB_URL") || "http://localhost:8086").replace(/\/+$/, "");
const influxOrg = env.get("INFLUXDB_ORG") || "industrial_iot";
const influxBucket = env.get("INFLUXDB_BUCKET") || "motor_telemetry";
const influxToken = env.get("INFLUXDB_TOKEN") || "my-secure-placeholder-token";

// 1. Tag escaping (commas, spaces, equal signs)
const rawDeviceId = String(normalized.device_id || "").trim();
const escapedDeviceId = rawDeviceId
    .replace(/\\/g, "\\\\")
    .replace(/,/g, "\\,")
    .replace(/ /g, "\\ ")
    .replace(/=/g, "\\=");

// 2. String field escaping (enclosed in double quotes, backslashes and quotes escaped)
const rawFault = String(normalized.fault_type || "").trim();
const escapedFault = rawFault
    .replace(/\\/g, "\\\\")
    .replace(/"/g, '\\"');

// 3. Numeric float formatting
const health = Number(normalized.health_index);
const rul = Number(normalized.rul_hours);

// 4. Timestamp conversion to ms epoch
let tsMs = Date.now();
if (normalized.timestamp) {
    const parsed = new Date(normalized.timestamp).getTime();
    if (!isNaN(parsed) && parsed > 0) {
        tsMs = parsed;
    }
}

// 5. Construct Line Protocol: predictions,device_id=<tag> fault_type="<val>",health_index=<float>,rul_hours=<float> <epoch_ms>
const lineProtocol = `predictions,device_id=${escapedDeviceId} fault_type="${escapedFault}",health_index=${health},rul_hours=${rul} ${tsMs}`;

// Prepare HTTP request message
msg.telemetry = normalized;
msg.url = `${influxUrl}/api/v2/write?org=${encodeURIComponent(influxOrg)}&bucket=${encodeURIComponent(influxBucket)}&precision=ms`;
msg.headers = {
    "Authorization": `Token ${influxToken}`,
    "Content-Type": "text/plain; charset=utf-8"
};
msg.method = "POST";
msg.payload = lineProtocol;

return msg;

// Handles network/connection failures to InfluxDB without crashing Node-RED
msg.payload = {
    status: "DB_UNAVAILABLE",
    disposition: "WRITE_FAILED",
    reason: "InfluxDB network unreachable or connection refused",
    error_message: (msg.error && msg.error.message) ? msg.error.message : "Connection failed",
    device_id: msg.telemetry ? msg.telemetry.device_id : "unknown",
    target_url: msg.url,
    gateway_received_at: (msg.telemetry && msg.telemetry.gateway_received_at) ? msg.telemetry.gateway_received_at : new Date().toISOString()
};
return msg;

// InfluxDB v2 returns HTTP 204 No Content upon successful write
const statusCode = msg.statusCode;
if (statusCode === 204) {
    msg.payload = {
        status: "DB_WRITE_SUCCESS",
        disposition: "STORED",
        status_code: 204,
        device_id: msg.telemetry ? msg.telemetry.device_id : "unknown",
        telemetry: msg.telemetry,
        stored_at: new Date().toISOString()
    };
    return [msg, null];
} else {
    msg.payload = {
        status: "DB_WRITE_ERROR",
        disposition: "REJECTED_BY_DB",
        status_code: statusCode,
        db_response: msg.payload,
        device_id: msg.telemetry ? msg.telemetry.device_id : "unknown",
        failed_at: new Date().toISOString()
    };
    return [null, msg];
}
